import { IngestionEventTracking } from './ingestion-event-tracking.entity';
import { AppLogger } from '@/common/logger/app-logger';
import { IngestionCleansingJobConfigService } from '@/config/ingestion-cleansing-job/ingestion-cleansing-job.service';

@Injectable()
export class IngestionEventTrackingService {
  private readonly logger = new AppLogger(IngestionEventTrackingService.name);

  public constructor(
    @InjectRepository(IngestionEventTracking)
    private readonly ingestionEventTrackingRepository: Repository<IngestionEventTracking>,
    private readonly ingestionCleansingJobConfigService: IngestionCleansingJobConfigService,
  ) {}

  public async deleteExpiredIngestionEventTracking(): Promise<{
    deletedCount: number;
  }> {
    try {
      const retentionDays =
        -(await this.ingestionCleansingJobConfigService.dataIngestionWorkdataRetentionDays()); // Adjust the retention period as needed
      const result = await this.ingestionEventTrackingRepository
        .createQueryBuilder()
        .delete()
        .from(IngestionEventTracking)
        .where(
          'updated_at < DATEADD(DAY, :retentionDays, CURRENT_TIMESTAMP) ',
          {
            retentionDays,
          },
        )
        .execute();

      this.logger.log(
        `Deleted ${result.affected} expired ingestion event tracking records.`,
      );
      return { deletedCount: result.affected ?? 0 };
    } catch (error) {
      this.logger.error(
        'Failed to delete expired ingestion event tracking records',
        error.stack,
      );
      throw new Error(
        'Failed to delete expired ingestion event tracking records',
      );
    }
  }
}

