@Injectable()
export class TransferService {
  private readonly logger = new AppLogger(TransferService.name);

  public constructor(
    // Inject the repository for Container entity
    @InjectRepository(Transfer)
    private readonly transferRepo: Repository<Transfer>,
  ) {}

  public async create(transfer: CreateTransferDto): Promise<void> {
    await this.transferRepo.insert(transfer);
  }

  public findAll(): Promise<Array<Transfer>> {
    return this.transferRepo.find();
  }

  public async findTransferById(
    transferIdList: Array<number>,
    plant: number,
  ): Promise<Record<number, TransferByIdsResponseDto>> {
    const result: Record<number, TransferByIdsResponseDto> = {};
    try {
      const transfers = await this.transferRepo.find({
        select: [
          'transferId',
          'containerId',
          'destinationLocation',
          'createdOn',
        ],

        where: {
          plant,
          transferId: In(transferIdList),
        },
      });
      if (transfers) {
        for (const transfer of transfers) {
          const { transferId, ...data } = transfer;
          result[transferId] = { transferId, ...data };
        }
        return result;
      }
      return result;
    } catch (error) {
      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          `Failed to retrieve tansfer [plant: ${plant}]: ${error.message}`,
        );
      }
      return result;
    }
  }

  public async findTransferDetailsByContainers(
    containerIdList: Array<string>,
    plant: number,
  ): Promise<Record<string, TransferByContainerResponseDto>> {
    const result: Record<string, TransferByContainerResponseDto> = {};
    try {
      const query = `DECLARE @containerId NVARCHAR(MAX) = @1;
WITH ids AS (
    SELECT value AS id
    FROM STRING_SPLIT(@containerId, ',')
  )
SELECT
    t.destination_location AS destinationLocation,
    t.created_on          AS createdOn,
    t.container_id        AS containerId
FROM ids AS c
CROSS APPLY (
    SELECT TOP (1)
        t.destination_location,
        t.created_on,
        t.container_id
    FROM transfer AS t
    WHERE t.plant = @0
      AND t.transfer_closed = 1
      AND t.container_id = c.id
    ORDER BY t.transfer_id DESC
) AS t;
`;
      const transfers = await this.transferRepo.query(query, [
        plant,
        containerIdList.join(','),
      ]);
      if (transfers.length >= 0) {
        for (const transfer of transfers) {
          result[transfer.containerId] = {
            createdOn: transfer.createdOn,
            destinationLocation: transfer.destinationLocation,
          };
        }
        return result;
      }
      return result;
    } catch (error) {
      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          `Failed to retrieve tansfer by container id list [plant: ${plant}]: ${error.message}`,
        );
      }
      return result;
    }
  }
}

